/// ``enabled`` is config truth; ``listening`` is this caller's armed detector; ``audio_silent`` means armed but deaf (see ``hint``).
public struct WakeStatusResult: Codable, Sendable {
    public let listening: Bool
    public let ownedByCaller: Bool
    public let ownerSurface: String?
    public let phrase: String
    public let provider: String
    public let configuredSurface: String
    public let inputDevice: WakeInputDevice
    public let available: Bool
    public let hint: String
    public let enabled: Bool
    public let audioSilent: Bool
    public let capture: String
    public let localInputAvailable: Bool
    public let sampleRate: Int64
    public let frameLength: Int64
    public enum CodingKeys: String, CodingKey {
        case listening = "listening"
        case ownedByCaller = "owned_by_caller"
        case ownerSurface = "owner_surface"
        case phrase = "phrase"
        case provider = "provider"
        case configuredSurface = "configured_surface"
        case inputDevice = "input_device"
        case available = "available"
        case hint = "hint"
        case enabled = "enabled"
        case audioSilent = "audio_silent"
        case capture = "capture"
        case localInputAvailable = "local_input_available"
        case sampleRate = "sample_rate"
        case frameLength = "frame_length"
    }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.listening = try c.decode(Bool.self, forKey: .listening)
        self.ownedByCaller = try c.decode(Bool.self, forKey: .ownedByCaller)
        self.ownerSurface = try c.decodeIfPresent(String.self, forKey: .ownerSurface)
        self.phrase = try c.decode(String.self, forKey: .phrase)
        self.provider = try c.decode(String.self, forKey: .provider)
        self.configuredSurface = try c.decode(String.self, forKey: .configuredSurface)
        self.inputDevice = try c.decode(WakeInputDevice.self, forKey: .inputDevice)
        self.available = try c.decode(Bool.self, forKey: .available)
        self.hint = try c.decode(String.self, forKey: .hint)
        self.enabled = try c.decode(Bool.self, forKey: .enabled)
        self.audioSilent = try c.decode(Bool.self, forKey: .audioSilent)
        self.capture = try c.decode(String.self, forKey: .capture)
        self.localInputAvailable = try c.decode(Bool.self, forKey: .localInputAvailable)
        self.sampleRate = try c.decode(Int64.self, forKey: .sampleRate)
        self.frameLength = try c.decode(Int64.self, forKey: .frameLength)
    }
}

